def test_pass_rate():
    assert pass_rate([50, 49, 100, 0]) == 0.5
    assert pass_rate([]) == 0.0
    assert pass_rate([80]) == 1.0
    assert pass_rate([10, 20, 30]) == 0.0


def test_pass_rate_depends_on_the_scores():
    assert pass_rate([60, 60]) != pass_rate([60, 40])


def test_pass_rate_stays_a_fraction():
    for scores in ([], [0], [100], [0, 100], [50] * 7):
        assert 0.0 <= pass_rate(scores) <= 1.0

def test_passes():
    assert passes(50) is True
    assert passes(49) is False
    assert passes(100) is True
    assert passes(0) is False
    assert passes(49.5) is False


def test_passes_depends_on_the_score():
    assert passes(10) != passes(90)


def test_passes_is_a_bool():
    assert isinstance(passes(75), bool)
